};

/**
 * @method
 * @name moveData_OnClick
 * @description moveData 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.moveData_OnClick = function() {
    try {
        const mv_filenm = mv_attach_file_nm.getValue();
        if (scwin.resoroomId === 'input') {
            dts_fileData.setCellData(dts_fileData.getRowPosition(), "fileInfo", moveData.getValue());
        } else {
            /*
    		if (mvFileExist  == 'Y') {
    dts_fileDataUpdate.setNameValue(dts_fileDataUpdate.rowposition, "fileInfo",moveData.Value) ;
    		} else {
    dts_fileData.setNameValue(dts_fileData.rowposition, "fileInfo",moveData.Value) ;
    		}
             */
            dts_fileData.setCellData(dts_fileData.getRowPosition(), "fileInfo", moveData.getValue());
        }
        mv_attach_file_nm.setValue(moveData.getValue());
        if (moveData.getValue() === "") {
            mv_attach_file_nm.setValue(mv_filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30305.moveData_OnClick" });
    }
};

