/**
 * @method
 * @name btn_lineadd_onclick
 * @description 「파일추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_lineadd_onclick = async function() {
    try {
        if (scwin.resoroomId !== "input") {
            scwin.fileRowcount = dts_fileList.getRowCount();
        }
        scwin.fileRowcount++;
        if (scwin.fileRowcount >= 3) {
            await $c.win.alert("더이상 추가하실수 없습니다.");
            scwin.fileRowcount = 3;
        } else {
            dts_fileList.insertRow();
            inf_find.open();
            if (inf_find.getValue() !== "") {
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", dts_fileList.getRowPosition());
                file_name.setValue(inf_find.getValue());
            } else {
                dts_fileList.removeRow(dts_fileList.getRowPosition());
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30305.btn_lineadd_onclick" });
    }
};

/**
 * @method
 * @name btn_linedelete_onclick
 * @description 「파일삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_linedelete_onclick = function() {
    try {
        if (scwin.fileRowcount > 0) scwin.fileRowcount--;
        dts_fileList.removeRow(dts_fileList.getRowPosition());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30305.btn_linedelete_onclick" });
    }
};

/**
 * @method
 * @name inf_find_OnClick
 * @description inf_find 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.inf_find_OnClick = function() {
    try {
        const filenm = file_name.getValue();
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
        if (inf_find.getValue() === "") {
            file_name.setValue(filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30305.inf_find_OnClick" });
    }
};

