///////// 4. 서브미션 콜백 영역 /////////
/**
     * @method
     * @name singleRead
     * @description IR자료실 개별조회
     * @returns {Promise<void>}
     * @hidden N
     */
scwin.singleRead = async function() {
    // IR자료실 개별조회
    trs_Read.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Read",
        action : "/IRMgt.do",
        ref : "dts_irDataRoomSingle,dts_fileData,dts_fileList",
        target : "trs_Read=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name update
 * @description IR자료실 수정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    // IR자료실 수정
    if (txb_isur_cd.getValue() === "" || txb_isur_cd.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "법인코드(명)"));
        txb_isur_cd.focus();
        return;
    }
    if (title.getValue() === "" || title.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        title.focus();
        return;
    }
    if (!await scwin.checkMaxLength1(title, 200, "제목")) {
        title.setValue("");
        title.focus();
        return false;
    }

    // 기능 변경으로 국문/영문 모두에서 IR개최일 수정할 수 있도록 변경 20130123_by LDJ
    /*
    if( koreng_tp_cd.CodeValue == '1') {
    	txb_irhlddate.Text = "";
    }
     */

    /*
    // 동영상 필수 제거 : 2008.10.22
    if(mv_attach_file_nm.value == "" || mv_attach_file_nm.value.indexOf(" ") == "" ) {
    	alert("[동영상 파일은] 반드시 첨부하셔야합니다.");
    	mv_attach_file_nm.focus();
    	return;
    }
     */

    // 동영상이 없으면 첨부파일은 있어야함.
    if (mv_attach_file_nm.getValue() === "" || mv_attach_file_nm.getValue().indexOf(" ") === "") {
        let fileCnt = dts_fileList.getRowCount();
        if (fileCnt <= 0) {
            await $c.win.alert("[동영상 파일 또는 첨부파일]은 반드시 첨부하셔야합니다.");
            mv_attach_file_nm.focus();
            return;
        }
    }
    if (content.text === "" || content.text.indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "내용"));
        content.Focus();
        return;
    }
    if (!await scwin.checkMaxLength2(content, 200, "내용")) {
        content.text = "";
        content.focus();
        return false;
    }
    if (cast_yn.getValue() === 'Y' & submit_yn.getValue() === 'N') {
        // 상장법인제출여부가 Y가 아니면 공개여부를 Y로 설정할 수 없음
        await $c.win.alert("[상장법인 제출여부] 가 Y일 경우에만 [공개여부]를 YES로 설정 가능합니다.");
        cast_yn.focus();
        cast_yn.setValue('N');
        return;
    }
    let rtn = confirm('내용을 수정 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        /*
        if(dts_fileDataUpdate.NameString(dts_fileDataUpdate.RowPosition,"fileInfo") == "") {
        //alert("Reset=Y");
        	dts_fileDataUpdate.Reset();
        }

        trs_Update.Action="/IRMgt.do?method=modifyIRDataRoom&resoroom_id="+resoroomId;
        trs_Update.KeyName="toinb_dataid4";
        trs_Update.KeyValue="JSP(I:pInput1=dts_irDataRoomSingle,I:pInput2=dts_fileDataUpdate,I:pInput3=dts_fileList)";
        trs_Update.Post();
         */

        trs_Update.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Update",
            action : "/IRMgt.do",
            ref : "dts_irDataRoomSingle,dts_fileData,dts_fileList",
            target : "trs_Update=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

